// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: attackerFunding (amount attacker will deposit), victimFunding (amount victim will deposit), victim address
    // We fuzz amounts and the victim address; attacker is deployed helper contract.
    function testFuzz_property(uint256 attackerFunding, uint256 victimFunding, address victim) public {
        // keep amounts in a reasonable range (but wide)
        attackerFunding = bound(attackerFunding, 1 wei, 1 ether);
        victimFunding = bound(victimFunding, 1 wei, 1 ether);
        // victim must be a non-zero, non-contract (we can allow any address but avoid zero address)
        vm.assume(victim != address(0));

        // deploy attacker helper which will re-enter on receive
        Attacker attacker = new Attacker(address(c));

        // Fund attacker and victim
        vm.deal(address(attacker), attackerFunding);
        vm.deal(victim, victimFunding);

        // Attacker deposits some funds to c
        vm.prank(address(attacker));
        attacker.deposit{value: attackerFunding}();

        // Victim deposits funds to c
        vm.prank(victim);
        (bool okDeposit, ) = address(c).call{value: victimFunding}("");
        require(okDeposit);

        // Now victim calls withdraw (this will trigger withdraw on c and allow attacker to re-enter during the external call if mutant exists)
        vm.prank(victim);
        // call withdraw; if it reverts the try/catch would be needed, but both variants should not revert under normal conditions
        c.withdraw();

        // Single assertion: in the correct contract, after withdraw completes the victim's recorded balance must be zero
        // This reads the public getter balances(victim) and asserts it's zero. The buggy mutant can leave it non-zero for some inputs due to reentrancy interaction.
        assertTrue(c.balances(victim) == 0);
    }
}

// Minimal reentrant attacker: on receiving funds it will call withdraw on c to attempt to exploit ordering
contract Attacker {
    C public target;
    constructor(address _t) {
        target = C(_t);
    }
    // deposit helper
    function deposit() external payable {
        // forward deposit to target via fallback (target has fallback payable that credits balances[msg.sender])
        (bool s, ) = address(target).call{value: msg.value}("");
        require(s);
    }
    // receive will try to re-enter withdraw on target
    receive() external payable {
        // attempt reentrancy
        // ignore success/failure
        (bool s, ) = address(target).call(abi.encodeWithSignature("withdraw()"));
        // silence unused var
        s;
    }
}

