        victimFund = bound(victimFund, 1, 1 ether);

        // Deploy attacker helper which re-enters during receive to exploit wrong ordering
        Attacker attacker = new Attacker(c);

        // Set up balances for attacker and victim in contract c
        address attackerAddr = address(attacker);
        address victim = address(0xBEEF);

        vm.deal(attackerAddr, attackerFund);
        vm.deal(victim, victimFund);

        // Attacker funds the contract so it has a balance to steal
        vm.prank(attackerAddr);
        // route through attacker so its fallback can reenter when it receives funds
        // attacker will first call c with value to fund its balances[attacker]
        (bool sent,) = address(c).call{value: attackerFund}(
            abi.encodeWithSignature("fallback()")
        );
        require(sent);

        // Victim funds the contract (normal EOA)
