import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: funding amount and attacker/depositor addresses
    function testFuzz_property(uint256 depositAmount, address depositor) public {
        // keep amounts reasonable and depositor non-zero
        vm.assume(depositor != address(0));
        depositAmount = bound(depositAmount, 1, 1 ether);

        // Deploy a reentrant attacker that will call back into c when receiving funds
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Fund depositor and attacker so they can make deposits
        vm.deal(depositor, depositAmount);
        vm.deal(address(attacker), 1 ether);

        // depositor funds the contract
        vm.prank(depositor);
        (bool ok, ) = address(c).call{value: depositAmount}("");
        require(ok);

        // attacker also funds the contract a bit so it has balance to steal
        vm.prank(address(attacker));
        (ok, ) = address(c).call{value: 0.5 ether}("");
        require(ok);

        // Now have depositor call withdraw while attacker will reenter during the external call
        // The attacker is coded to reenter on receive and call withdraw again
        vm.prank(depositor);
        // call withdraw (no value) — track whether it completes
        bool completed;
        try c.withdraw() {
            completed = true;
        } catch {
            completed = false;
        }

        // General rule: after a depositor who funded the contract calls withdraw, the reference
        // implementation always sets balances(depositor) == 0. The mutant can be exploited by
        // a reentrant attacker to make balances(depositor) != 0 for some inputs.
        assertTrue(c.balances(depositor) == 0);
    }
}

// Minimal reentrant attacker: on receive, it calls withdraw on the target contract.
