    C target;
    bool reentered;
    constructor(C _t) {
        target = _t;
        reentered = false;
    }
    receive() external payable {
        // attempt a single reentrant call into withdraw
        if (!reentered) {
            reentered = true;
            // ignore success/failure
            try target.withdraw() {} catch {}
        }
    }
