pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: amount to deposit (amt) and an address that will act as the attacker (attackerAddr)
    function testFuzz_property(uint256 amt, address attackerAddr) public {
        // keep amount reasonable and non-zero
        amt = bound(amt, 1, 1 ether);
        // avoid the zero address for attacker (must be a contract we deploy below)
        vm.assume(attackerAddr != address(0));

        // Deploy a reentrant attacker contract that will call back into c during its receive.
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        address payable attackerPayable = payable(address(attacker));

        // Fund both the attacker contract and a benign caller (use this test contract as benign caller)
        vm.deal(address(this), amt);
        vm.deal(attackerPayable, amt);

        // 1) benign caller (this) deposits amt into c
        // call fallback by sending ether
        c.fallback{value: amt}();
        // ensure the recorded balance for this contract is amt
        assert(c.balances(address(this)) == amt);

        // 2) attacker deposits amt into c
        vm.prank(attackerPayable);
        // trigger fallback to credit attacker's balance
        (bool ok,) = attackerPayable.call{value: amt}("", 0);
        // some environments might not allow low-level with 2 args; if that fails, just call via attacker helper
        if (!ok) {
            vm.prank(attackerPayable);
            (bool ok2,) = attackerPayable.call{value: amt}("");
            require(ok2);
        }
        // ensure attacker's recorded balance is amt
        assert(c.balances(attackerPayable) == amt);

        // Record contract balance before withdraw
        uint256 before = address(c).balance;

        // Now perform withdraw from this contract (benign caller)
        // This will transfer this contract's stored balance to msg.sender (this) via external call
        // The attacker is set up to reenter when it receives funds from its own withdraw.
        // Execute withdraw as the benign caller
        c.withdraw();

        // After reference behavior, caller's recorded balance should be zero and contract balance decreased by amt
        // The single assertion reads c only and must be true for the reference and falsified by the mutant for some inputs
        // We assert that the contract's stored balance for the benign caller is zero and that address(c).balance == before - amt
        // Combine into one boolean expressed by public getters: balances(this) == 0 && address(c).balance == before - amt
        bool prop = (c.balances(address(this)) == 0) && (address(c).balance == before - amt);
        assertTrue(prop);
    }
}

// Minimal reentrant attacker: when it receives ether, it will attempt to call withdraw on C once
contract ReentrantAttacker {
    C public target;
    bool public reentered;

    constructor(C _target) payable {
        target = _target;
        reentered = false;
    }

    // receive funds by calling the fallback of C to deposit
    receive() external payable {}

    // Helper to deposit into target via its fallback
    fallback() external payable {}

    // Attack: when receiving ether during its own withdraw, reenter target.withdraw()
    // We implement receive to reenter once.
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // attempt to reenter withdraw on target
            // use low-level call to avoid bubbling revert unexpectedly
            (bool s,) = address(target).call(abi.encodeWithSignature("withdraw()"));
            // ignore success/failure here; the property is about final stored balances
            s;
        }
    }
}

