pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and deposit amount.
    // General rule: after a successful withdraw from address depositor, c.balances(depositor) == 0.
    // The buggy mutant that removed the balances reset will leave it non-zero for some inputs.
    function testFuzz_property(address depositor, uint96 amt) public {
        // keep depositor nonzero and amount within reasonable gas/ETH bounds
        vm.assume(depositor != address(0));
        uint256 amount = uint256(amt);
        vm.assume(amount > 0);

        // Fund the depositor EOA so they can send ETH to the contract
        vm.deal(depositor, amount);

        // Make a deposit by calling the fallback (send ETH)
        vm.prank(depositor);
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "deposit failed");

        // Sanity: recorded balance should equal deposit
        uint256 before = c.balances(depositor);
        require(before == amount, "deposit not recorded");

        // Now have depositor call withdraw
        vm.prank(depositor);
        // withdraw is external and will forward ETH back to depositor
        // capture success via try/catch would be for revert differences; here withdraw should succeed
        try c.withdraw() {
            // After successful withdraw, the reference implementation sets balances[depositor] to 0.
            // The mutant that removed the reset will leave it unchanged (non-zero) for some inputs.
        } catch {
            // If withdraw reverts, treat as failure of scenario; skip by assuming revert shouldn't happen
            revert("withdraw reverted unexpectedly");
        }

        // Exactly one assertion: the invariant that the reference preserves for all inputs
        assertTrue(c.balances(depositor) == 0);
    }
}

