pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to deposit and an attacker address (as uint160 to allow contract deploy)
    function testFuzz_property(uint256 depositAmount, uint160 attackerSalt) public {
        // keep amounts reasonable and nonzero but wide
        depositAmount = bound(depositAmount, 1, 1 ether);

        // deploy two participants: depositor (EOA) and attacker (contract) using the fuzzed salt
        address depositor = address(uint160(0xDeaDbeefdEAdbeefdEadbEEFdeadbeEFdEaDbeeF));
        // fund depositor so they can send
        vm.deal(depositor, depositAmount);

        // deploy an attacker contract whose receive() will reenter withdraw
        Attacker attacker = new Attacker(c);
        address attackerAddr = address(attacker);
        // fund attacker so it can act during fallback
        vm.deal(attackerAddr, 0);

        // depositor deposits into c via fallback
        vm.prank(depositor);
        (bool ok1, ) = address(c).call{value: depositAmount}("");
        require(ok1);

        // also give attacker a balance in the mapping so it can be targeted/modified
        // fund attacker by calling fallback from attacker address
        vm.deal(attackerAddr, depositAmount);
        vm.prank(attackerAddr);
        (bool ok2, ) = address(c).call{value: depositAmount}("");
        require(ok2);

        // Record total stored balances BEFORE the vulnerable withdraw
        // We only have public getter balances(address) so sample both depositor and attacker
        uint256 before_depositor = c.balances(depositor);
        uint256 before_attacker = c.balances(attackerAddr);
        uint256 total_before = before_depositor + before_attacker;

        // Now perform withdraw as depositor, but route the call such that attacker can reenter.
        // To allow reentrancy attempt, attacker contract will call back into c.withdraw during its receive().
        // We let the attacker be the callee by having depositor send funds to attacker first, then attacker calls withdraw on depositor's behalf via reentrancy when receiving refunds.
        // Start a prank so depositor calls withdraw; we make attacker set itself as a callee by transferring Ether to attacker in a way that triggers its fallback during withdraw's external call.

        // Configure attacker to attempt reentrancy when it receives Ether from c
        attacker.setTarget(depositor);

        // Now call withdraw as depositor. During the external call to msg.sender.call in withdraw, if reentrancy is possible
        // the attacker won't be triggered unless the withdraw sends to attacker; to force a scenario where the external call goes to attacker,
        // we instead have the depositor be the attacker contract itself (so reentrancy is possible). Therefore we use the attacker contract as the withdraw caller.

        // So perform withdraw as the attacker contract (it has a balance in the mapping). The attacker.receive will reenter c.withdraw and try to manipulate other balances.
        vm.prank(attackerAddr);
        // attacker initiates withdraw; capture revert/ok via try/catch on low-level call since withdraw is external
        // But we must call C.withdraw() directly
        try c.withdraw() {
            // nothing
        } catch {}

        // After the withdraw completes, compute total of stored balances for the two addresses again
        uint256 after_depositor = c.balances(depositor);
        uint256 after_attacker = c.balances(attackerAddr);
        uint256 total_after = after_depositor + after_attacker;

        // The general rule: the reference contract preserves the sum of stored balances (total_before == total_after)
        // The mutant lacking the reentrancy lock can change other addresses' stored balances via reentrancy, making total_after != total_before
        assertTrue(total_before == total_after);
    }
}

// Minimal attacker that tries to reenter and manipulate balances during receive
contract Attacker {
    C immutable c;
    address target;
    bool reentered;
    constructor(C _c) {
        c = _c;
    }
    function setTarget(address _t) external { target = _t; }
    receive() external payable {
        // attempt to reenter only once to avoid infinite loop
        if (!reentered) {
            reentered = true;
            // try to withdraw on behalf of target (reentering withdraw)
            // This will only succeed if c's withdraw calls back into this contract in a way that allows reentrancy
            // We call withdraw directly to try to trigger the mutant behavior
            try c.withdraw() {
            } catch {}
        }
    }
}

