    function setUp() public { c = new C(); }

    // fuzzed params: depositor (address) and deposit amount
    function testFuzz_property(address depositor, uint128 amount) public {
        // keep depositor non-zero and amount > 0 and not insanely large
        vm.assume(depositor != address(0));
        uint256 amt = bound(uint256(amount), 1, 1 ether);

        // Deploy an attacker contract that will reenter c.withdraw when receiving ether
        Attacker attacker = new Attacker(c);

        // fund depositor and attacker so they can send deposits
        vm.deal(depositor, amt);
        vm.deal(address(attacker), amt);

        // Depositor deposits into c
        vm.prank(depositor);
        (bool okDeposit,) = address(c).call{value: amt}("");
        require(okDeposit);

        // Also deposit some funds under attacker to be present in C's balance
        vm.prank(address(attacker));
        (bool okDeposit2,) = address(c).call{value: amt}("");
        require(okDeposit2);

        // Now have attacker hold some of c's outgoing call target: attacker will re-enter
        // Fuzz decides whether the withdraw recipient is attacker (reentrant) or depositor (EOA)
        // We call withdraw from depositor but route the msg.sender to attacker by making attacker the depositor
        // To allow fuzz to explore, we use depositor variable to decide who calls withdraw: if depositor is contract-like
        // We instead use the attacker to call withdraw to receive funds (and re-enter). The fuzzed depositor paid earlier.

        // Attacker will trigger withdraw and re-enter during the external call
        // Make attacker the caller of withdraw so it receives the funds and can reenter
        vm.prank(address(attacker));
        try c.withdraw() {
            // withdraw completed
        } catch {
            // ignore
        }

        // The universal property to assert: after withdraw completes, the recorded balance for the original depositor must be zero
        // This holds for the reference contract for all inputs, but the mutant (without the require lock) can leave it non-zero
        uint256 bal = c.balances(depositor);
        assertTrue(bal == 0);
    }
}

// Minimal attacker that re-enters C.withdraw in its receive()
contract Attacker {
    C public target;
    bool public reentered;
    constructor(C _target) payable {
        target = _target;
        reentered = false;
    }
    receive() external payable {
        // on receiving funds from target.withdraw, try to re-enter once
        if (!reentered) {
            reentered = true;
            // call withdraw again to attempt reentrancy
            try target.withdraw() {
            } catch {
            }
        }
    }
}

