pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { 
        c = new C();
        attacker = new Attacker();
    }

    // fuzzed parameters: deposit amount and whether attacker will trigger reentrancy
    function testFuzz_property(uint256 amount, bool doReenter) public {
        // keep amount in a sensible range (nonzero and not exceeding a wallet sized bound)
        amount = bound(amount, 0, 1 ether);
        address payer = address(this);

        // fund payer and attacker
        vm.deal(payer, 1 ether);
        vm.deal(address(attacker), 1 ether);

        // 1) deposit into contract from attacker (so balances[attacker]==amount)
        if (doReenter) {
            // attacker will deposit by calling fallback payable
            vm.prank(address(attacker));
            // deposit amount from attacker into c
            (bool s, ) = address(c).call{value: amount}("{}");
            require(s);

            // now trigger withdraw from attacker which may try to reenter
            // call withdraw via attacker which will attempt a reentrant call in its receive()
            bool ok;
            try attacker.withdrawFrom(address(c)) {
                ok = true;
            } catch {
                ok = false;
            }

            // After withdraw returns (or reverts), the correct contract guarantee:
            // balances[attacker] must be 0 and address(c).balance decreased by amount
            // We read balances via the public getter and address(c).balance.
            uint256 remaining = c.balances(address(attacker));
            // Single assertion expressing the invariant that withdraw clears the recorded balance
            assertTrue(remaining == 0, "balances[attacker] should be zero after withdraw");
        } else {
            // Non-reentrant simple deposit and withdraw by this contract
            vm.prank(payer);
            (bool s, ) = address(c).call{value: amount}("");
            require(s);

            // perform withdraw normally
            bool ok;
            try c.withdraw() {
                ok = true;
            } catch {
                ok = false;
            }

            // For the correct contract, after withdraw balances[payer]==0
            uint256 remaining = c.balances(payer);
            assertTrue(remaining == 0, "balances[payer] should be zero after withdraw");
        }
    }
}

// Minimal adversarial helper that attempts reentrancy during receive()
contract Attacker {
    C target;
    bool first = true;

    // deposit helper
    function withdrawFrom(address _c) external {
        target = C(_c);
        // attempt to call withdraw on target; since attacker has a balance, this will trigger receive()
        target.withdraw();
    }

    // receive will attempt reentrant withdraw once
    receive() external payable {
        if (first) {
            first = false;
            // attempt reentrancy
            // use low-level call to avoid consuming too much gas in case of reverted reentry
            (bool s, ) = address(target).call(abi.encodeWithSignature("withdraw()"));
            // ignore result; behavior (revert or success) is what test observes via balances getter
        }
    }
}

