pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the depositor address and deposit amount
    function testFuzz_property(address depositor, uint96 amount) public {
        // keep amount in a sensible gas/ether range but wide
        uint256 amt = bound(uint256(amount), 1, 1 ether);

        // fund the depositor EOA so they can send value
        vm.deal(depositor, amt);

        // perform the deposit via fallback by having depositor send value
        vm.prank(depositor);
        (bool sent,) = address(c).call{value: amt}("");
        // deposit should succeed (fallback is payable)
        assertTrue(sent);

        // try withdraw and capture whether it succeeds
        bool ok;
        vm.prank(depositor);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: on the correct contract, withdraw always succeeds for any depositor/amount
        // (the mutant inverts the lock check causing withdraw to revert for some inputs)
        assertTrue(ok);
    }
}
